flowchart TD
    A[Start] --> B{Need relational?}
    B -->|Yes| C{Strong consistency required?}
    B -->|No| D{Schema flexibility needed?}
    C -->|Yes| E[PostgreSQL]
    C -->|No| F[MySQL]
    D -->|Yes| G[MongoDB]
    D -->|No| H{High write throughput?}
    H -->|Yes| I[Cassandra]
    H -->|No| J[Redis]

erDiagram
    USER {
        int id PK
        string username
        string email
        string password_hash
        datetime created_at
    }
    POST {
        int id PK
        int user_id FK
        string title
        text content
        datetime created_at
    }
    COMMENT {
        int id PK
        int post_id FK
        int user_id FK
        text body
        datetime created_at
    }
    TAG {
        int id PK
        string name
    }
    POST_TAG {
        int post_id PK,FK
        int tag_id PK,FK
    }
    CATEGORY {
