classDiagram
    class Account {
        +String accountNumber
        +double balance
        +void deposit(amount)
        +void withdraw(amount)
    }
    class SavingsAccount {
        +double interestRate
        +void applyInterest()
    }
    class CheckingAccount {
        +double overdraftLimit
        +void writeCheck(amount)
    }
    class Customer {
        +String name
        +String address
        +List~Account~ accounts
        +void addAccount(account)
    }
    class Transaction {
        +String id
        +Date date
        +double amount
        +String type
        +void execute()
    }
    class Bank {
        +String name
        +String routingNumber
        +List~Customer~ customers
        +void processTransaction(transaction)
    }
    Account <|-- SavingsAccount
    Account <|-- CheckingAccount
    Customer "1" --> "*" Account : owns
    Bank "1" --> "*" Customer : serves
    Account "1" --> "*" Transaction : records
    Bank "1" --> "*" Transaction : processes

classDiagram
    class Shape {
        +draw()
        +move(x: int, y: int)
        +resize(scale: float)
    }
    class Circle {
        +radius: float
    }
    class Rectangle {
        +width: float
        +height: float
    }
    class Triangle {
        +pointA: Point
        +pointB: Point
        +pointC: Point
    }
    class Point {
        +x: float
        +y: float
    }
    class Color {
        +r: int
        +g: int
        +b: int
        +a: int
    }
    class Canvas {
        +addShape(s: Shape)
        +removeShape(s: Shape)
        +clear()
    }
    class Renderer {
        +render(c: Canvas)
    }
    Shape <|-- Circle
    Shape <|-- Rectangle
    Shape <|-- Triangle
    Circle --> "1" Color : fill
    Rectangle --> "1" Color : fill
    Triangle --> "1" Color : fill
    Canvas "1" *-- "0..*" Shape : contains
    Renderer --> Canvas : renders

classDiagram
    class MP {+play()\n+pause()\n+stop()\n+next()\n+previous()}
    class Playlist {+addTrack()\n+removeTrack()\n+shuffle()}
    class Track {+title\n+duration\n+trackNumber}
    class Album {+title\n+releaseYear}
    class Artist {+name}
    class Library {+addTrack()\n+removeTrack()\n+search()}
    class Queue {+enqueue()\n+dequeue()}
    class UserSettings {+volume\n+theme\n+equalizer}
    MP "1" --> "1" Playlist : currentPlaylist
    MP "1" --> "1" Queue : playQueue
    MP "1" --> "1" Library : library
    MP "1" --> "1" UserSettings : settings
    Playlist "1" *-- "*" Track : contains
    Album "1" *-- "*" Track : includes
    Artist "1" *-- "*" Album : creates
    Track "1" --> "1" Album : partOf
    Track "1" --> "1" Artist : performedBy

